MODULE GPNORM_TRANS_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to GPNORM_TRANS
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IGP_SHAPE(3)
  INTEGER(KIND=C_INT) :: IPAVE_SHAPE(1)
  INTEGER(KIND=C_INT) :: IPMIN_SHAPE(1)
  INTEGER(KIND=C_INT) :: IPMAX_SHAPE(1)
END TYPE ARGS_INFO

END MODULE GPNORM_TRANS_ARGS_INFO_MOD

SUBROUTINE GPNORM_TRANS(PGP, KFIELDS, KPROMA, PAVE, PMIN, PMAX, LDAVE_ONLY, KRESOL)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_BOOL, C_PTR, C_LOC, C_NULL_PTR
USE GPNORM_TRANS_ARGS_INFO_MOD,  ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE GPNORM_TRANS_CPP_BINDING_SP(ARGS, KFIELDS, KPROMA, KAVE_ONLY, KRESOL, PGP, PAVE, PMIN, &
  &                                    PMAX) BIND(C, NAME="gpnorm_trans_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_BOOL, C_PTR
  USE GPNORM_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)    :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KFIELDS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPROMA
  LOGICAL(KIND=C_BOOL), VALUE,   INTENT(IN)    :: KAVE_ONLY
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KRESOL
  REAL(KIND=C_FLOAT),            INTENT(IN)    :: PGP(*)
  REAL(KIND=C_FLOAT),            INTENT(OUT)   :: PAVE(*)
  REAL(KIND=C_FLOAT),            INTENT(INOUT) :: PMIN(*)
  REAL(KIND=C_FLOAT),            INTENT(INOUT) :: PMAX(*)
END SUBROUTINE GPNORM_TRANS_CPP_BINDING_SP
SUBROUTINE GPNORM_TRANS_CPP_BINDING_DP(ARGS, KFIELDS, KPROMA, KAVE_ONLY, KRESOL, PGP, PAVE, PMIN, &
  &                                    PMAX) BIND(C, NAME="gpnorm_trans_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_BOOL, C_PTR
  USE GPNORM_TRANS_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)    :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KFIELDS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)    :: KPROMA
  LOGICAL(KIND=C_BOOL), VALUE,   INTENT(IN)    :: KAVE_ONLY
  TYPE(C_PTR),         VALUE,    INTENT(IN)    :: KRESOL
  REAL(KIND=C_DOUBLE),           INTENT(IN)    :: PGP(*)
  REAL(KIND=C_DOUBLE),           INTENT(OUT)   :: PAVE(*)
  REAL(KIND=C_DOUBLE),           INTENT(INOUT) :: PMIN(*)
  REAL(KIND=C_DOUBLE),           INTENT(INOUT) :: PMAX(*)
END SUBROUTINE GPNORM_TRANS_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),              INTENT(IN)    :: PGP(:,:,:)
REAL(KIND=JPRB),              INTENT(OUT)   :: PAVE(:)
REAL(KIND=JPRB),              INTENT(INOUT) :: PMIN(:)
REAL(KIND=JPRB),              INTENT(INOUT) :: PMAX(:)
INTEGER(KIND=JPIM),           INTENT(IN)    :: KFIELDS
INTEGER(KIND=JPIM),           INTENT(IN)    :: KPROMA
LOGICAL,                      INTENT(IN)    :: LDAVE_ONLY
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)    :: KRESOL

TYPE(ARGS_INFO) :: ARGS

LOGICAL(KIND=C_BOOL) :: LAVE_ONLY
TYPE(C_PTR) :: KRESOL_PTR
INTEGER(KIND=C_INT), TARGET :: IRESOL

ARGS%IGP_SHAPE = SHAPE(PGP, KIND=C_INT)
ARGS%IPAVE_SHAPE = SHAPE(PAVE, KIND=C_INT)
ARGS%IPMIN_SHAPE = SHAPE(PMIN, KIND=C_INT)
ARGS%IPMAX_SHAPE = SHAPE(PMAX, KIND=C_INT)

LAVE_ONLY = LDAVE_ONLY

IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL GPNORM_TRANS_CPP_BINDING_SP(ARGS, KFIELDS, KPROMA, LAVE_ONLY, KRESOL_PTR, PGP, PAVE, PMIN, &
  &                              PMAX)
#else
CALL GPNORM_TRANS_CPP_BINDING_DP(ARGS, KFIELDS, KPROMA, LAVE_ONLY, KRESOL_PTR, PGP, PAVE, PMIN, &
  &                              PMAX)
#endif

END SUBROUTINE GPNORM_TRANS
